<script setup>
import {reactive,ref,onMounted} from 'vue';import {ElMessage} from 'element-plus';import PageHeader from '../../components/common/PageHeader.vue';import {getProfile,updateProfile} from '../../api/profile.js';const form=reactive({name:'',phone:'',email:'',city:'',address:'',preferredStyle:''}),loading=ref(true),saving=ref(false);onMounted(async()=>{Object.assign(form,(await getProfile()).data);loading.value=false});async function save(){saving.value=true;await updateProfile(form);saving.value=false;ElMessage.success('个人资料已保存')}
</script>
<template><div class="page-shell"><div class="container profile-page"><PageHeader title="个人中心" description="维护联系信息和常用设计偏好。" :breadcrumbs="['首页','个人中心']"/><div class="profile-layout"><aside><div class="profile-avatar">{{form.name.slice(0,1)||'客'}}</div><h2>{{form.name||'客户'}}</h2><p>{{form.phone}}</p><nav><a class="active">基本资料</a><router-link to="/orders">我的订单</router-link><router-link to="/assistant">AI 定制助手</router-link></nav></aside><section><h2>基本资料</h2><el-skeleton v-if="loading" :rows="6" animated/><el-form v-else :model="form" label-position="top"><div class="profile-grid"><el-form-item label="称呼"><el-input v-model="form.name"/></el-form-item><el-form-item label="手机号"><el-input v-model="form.phone" disabled/></el-form-item><el-form-item label="电子邮箱"><el-input v-model="form.email"/></el-form-item><el-form-item label="所在城市"><el-input v-model="form.city"/></el-form-item><el-form-item label="详细地址" class="full"><el-input v-model="form.address"/></el-form-item><el-form-item label="偏好风格"><el-select v-model="form.preferredStyle"><el-option v-for="x in ['现代欧式','法式简约','现代原木','极简']" :key="x" :label="x" :value="x"/></el-select></el-form-item></div><el-button type="primary" :loading="saving" @click="save">保存修改</el-button></el-form></section></div></div></div></template>
<style scoped>.profile-page{max-width:980px}.profile-layout{display:grid;grid-template-columns:220px 1fr;background:#fff;border:1px solid var(--c-border)}.profile-layout>aside{padding:30px;border-right:1px solid var(--c-border)}.profile-avatar{width:64px;height:64px;border-radius:50%;display:grid;place-items:center;background:var(--c-deep);color:#fff;font:26px var(--font-display)}.profile-layout aside h2{font:500 20px var(--font-display);margin:14px 0 0}.profile-layout aside p{color:var(--c-muted);margin:2px 0 24px}.profile-layout nav{display:grid}.profile-layout nav a{padding:10px 0;border-bottom:1px solid var(--c-soft)}.profile-layout nav .active{color:var(--c-primary)}.profile-layout>section{padding:30px 38px}.profile-layout section h2{font:500 22px var(--font-display);margin:0 0 24px}.profile-grid{display:grid;grid-template-columns:1fr 1fr;gap:0 22px}.full{grid-column:1/-1}@media(max-width:700px){.profile-layout{grid-template-columns:1fr}.profile-layout>aside{border-right:0;border-bottom:1px solid var(--c-border)}.profile-layout>section{padding:26px 20px}.profile-grid{grid-template-columns:1fr}}</style>
